package com.mockarena.assessment.application;
import com.mockarena.assessment.domain.*; import com.mockarena.assessment.infrastructure.question.*; import org.springframework.stereotype.Service; import org.springframework.transaction.support.TransactionTemplate; import java.math.*; import java.time.*; import java.util.*;
@Service public class AttemptEvaluationService {
 private final AttemptRepository attempts;private final AttemptItemRepository items;private final AttemptItemResponseRepository responses;private final AttemptResultRepository results;private final AttemptItemResultRepository itemResults;private final QuestionEvaluationDataClient questions;private final TransactionTemplate tx;private final Clock clock=Clock.systemUTC();
 public AttemptEvaluationService(AttemptRepository a,AttemptItemRepository i,AttemptItemResponseRepository r,AttemptResultRepository ar,AttemptItemResultRepository ir,QuestionEvaluationDataClient q,TransactionTemplate t){attempts=a;items=i;responses=r;results=ar;itemResults=ir;questions=q;tx=t;}
 public AttemptResult evaluate(UUID attemptId){Attempt attempt=attempts.findById(attemptId).orElseThrow(AttemptNotFoundException::new);if(attempt.status()!=AttemptStatus.SUBMITTED)throw new IllegalStateException("Attempt is not submitted");AttemptResult prior=results.findById(attemptId).orElse(null);if(prior!=null&&prior.evaluationStatus()!=EvaluationStatus.FAILED)return prior;List<AttemptItem> route=items.findByAttemptIdOrderByGlobalPositionAsc(attemptId);Map<Integer,AttemptItemResponse> saved=new HashMap<>();responses.findByAttemptIdOrderByGlobalPositionAsc(attemptId).forEach(x->saved.put(x.globalPosition(),x));List<AttemptItem> mcq=route.stream().filter(x->"MCQ".equals(x.questionTypeCode())).toList();Map<UUID,McqEvaluationData> data=new HashMap<>();for(McqEvaluationData d:questions.resolve(mcq.stream().map(AttemptItem::questionVersionId).toList())){if(data.put(d.questionVersionId(),d)!=null)throw new IllegalStateException("Duplicate evaluation data");}if(data.size()!=mcq.size())throw new IllegalStateException("Incomplete evaluation data");Instant now=clock.instant();List<AttemptItemResult> computed=new ArrayList<>();BigDecimal score=BigDecimal.ZERO,max=BigDecimal.ZERO;boolean mixed=route.size()!=mcq.size();for(AttemptItem item:route){if(!"MCQ".equals(item.questionTypeCode())){computed.add(new AttemptItemResult(item,ItemEvaluationStatus.PENDING,null,null,null,null));continue;}AttemptItemResponse response=saved.get(item.globalPosition());if(response!=null&&!"MCQ".equals(response.questionTypeCode()))throw new IllegalStateException("Response type does not match attempt item");String selected=response==null?null:response.responsePayload().path("selectedOptionId").asText(null);McqScorer.Score s=McqScorer.score(selected,data.get(item.questionVersionId()));if(s.max().compareTo(BigDecimal.ZERO)<=0)throw new IllegalStateException("Invalid MCQ maximum score");score=score.add(s.awarded());max=max.add(s.max());computed.add(new AttemptItemResult(item,ItemEvaluationStatus.EVALUATED,s.outcome(),s.awarded(),s.max(),now));}EvaluationStatus status=mixed?EvaluationStatus.PARTIALLY_EVALUATED:EvaluationStatus.EVALUATED;BigDecimal percentage=mixed?null:score.multiply(BigDecimal.valueOf(100)).divide(max,4,RoundingMode.HALF_UP);AttemptResult aggregate=new AttemptResult(attemptId,status,mixed?null:score,mixed?null:max,percentage,mixed?null:now,mixed?null:now);return tx.execute(state->{Attempt current=attempts.findByIdForUpdate(attemptId).orElseThrow(AttemptNotFoundException::new);if(current.status()!=AttemptStatus.SUBMITTED)throw new IllegalStateException("Attempt is not submitted");AttemptResult existing=results.findById(attemptId).orElse(null);if(existing!=null&&existing.evaluationStatus()!=EvaluationStatus.FAILED)return existing;if(existing!=null)throw new IllegalStateException("Result state is not retryable");itemResults.saveAll(computed);return results.saveAndFlush(aggregate);});}
}
